/** 案件里存投影缓存的子目录（相对案件根）。 */
export const CASE_CACHE_DIR = join('工作区', '会话缓存')

/** 能当文件名的会话编号（DSH 的编号是 UUID）；别的写法只放内存。 */
export const SAFE_ID = /^[A-Za-z0-9_-][A-Za-z0-9._-]{0,199}$/

